/**
 * Which mark belongs to a broadcaster string from ESPN.
 *
 * ESPN sends the local affiliate as often as the network - "FOX59", "NBC 10",
 * "WBZ", "NFL Net", "Prime Video" all appear in one team's season - so this
 * matches on the network's name appearing anywhere in the string rather than on
 * equality. A call sign that carries no network name ("WBZ") matches nothing
 * and falls back to text, which is the right answer: we know it is a local
 * station, not which network's affiliate it is.
 */
export function networkMarkFor(network: string): NetworkMark | null {
  const name = network.toLowerCase();
  // Ordered longest-claim-first. "NFL Net" has to be tested before a bare
  // "nfl", "Paramount+" before "Paramount", and the streamers before the
  // broadcast networks they carry a simulcast of, or a substring test would
  // stop at the wrong one.
  if (name.includes("netflix")) return NETWORK_MARKS["netflix"] ?? null;
  if (name.includes("prime video") || name.includes("amazon")) {
    return NETWORK_MARKS["primevideo"] ?? null;
  }
  if (name.includes("paramount")) return NETWORK_MARKS["paramountplus"] ?? null;
  if (name.includes("peacock")) return NETWORK_MARKS["peacock"] ?? null;
  if (name.includes("youtube")) return NETWORK_MARKS["youtube"] ?? null;
  if (name.includes("nfl net") || name.includes("nfln")) {
    return NETWORK_MARKS["nfln"] ?? null;
  }
  if (name.includes("espn")) return NETWORK_MARKS["espn"] ?? null;
  if (name.includes("abc")) return NETWORK_MARKS["abc"] ?? null;
  if (name.includes("cbs")) return NETWORK_MARKS["cbs"] ?? null;
  if (name.includes("nbc")) return NETWORK_MARKS["nbc"] ?? null;
  if (name.includes("fox")) return NETWORK_MARKS["fox"] ?? null;
  return null;
}
